 const ax=axes(c,{xMin:-.5,xMax:3.5,yMax:ymax,xTicks:[0,1,2,3],xFormat:i=>labels[i],yFormat:money,xLabel:'Storey-range midpoint band',yLabel:'SGD / m²',bottom:50,top:35});
 if(!data.length){empty(c);$('#floorInsight').textContent='No transactions match the selected building-age group.';return;}
